"use strict";

import * as Rights from "approot/global/references/rights.js";

angular
	.module("irtech.netcity.school.statreports")
	.factory("fillIndicatorsRepositorySchool", (indicatorsRepository) => {
		var baseRep = indicatorsRepository.educInstIndicators;
		return {
			baseRep: indicatorsRepository.educInstIndicators,
			get: (indicatorGroupId) => baseRep.get(indicatorGroupId),
			save: (indicatorValues, groupIndicatorId) => baseRep.saveIndicatorValues(indicatorValues, groupIndicatorId),
			approve: (arrIndicatorGroups) => baseRep.approveIndicatorGroups(arrIndicatorGroups),
			getIndicatorGroups: () => baseRep.getGroups(),
			getIndicatorValues: (indicatorGroupId) => baseRep.getIndicatorValues(indicatorGroupId),
			getCalculatedIndicatorValues: (indicatorGroupId) => baseRep.getCalculatedIndicatorValues(indicatorGroupId)
		};
	})
	.controller("FillIndicators.View.School", ($scope, $alerts, $dialogs, $errorHandler, $collectionHelper, $controller, fillIndicatorsRepositorySchool) => {

		$scope.$parent.page = {
			parent: {
				title: "Статистическая отчетность",
				href: "/asp/Reports/StatReports/StatReports.asp?AT=" + appContext.at,
				postTo: true
			},
			title: "Заполнение отчетов вышестоящих организаций",
			//back: {
			//	href: "/asp/Reports/StatReports/StatReports.asp?AT=" + appContext.at
			//}
		};

		$scope.state = {
			hasFillAccess: _.contains(context.rights, Rights.arFillStatReports),
		}

		//наследование от базового контроллера
		$controller("FillIndicators.View.Common", { $scope, fillIndicatorsRepository: fillIndicatorsRepositorySchool, $alerts, $dialogs, $errorHandler, $collectionHelper });
	});


