const module = angular
	.module("irtech.netcity.school.statreports",
	[
		"ngRoute", "ngSanitize", "ngMessages", "ui.select", "uikit.alerts", "uikit.dialogs", "ui.bootstrap",
		"irtech.netcity.common", "ngFileUpload", "ui.tree", "netcity.helpers", "netcity.validation",
		"netcity.indicators.directives", "uikit.controls.controllers", "uikit.controls", "irtech.netcity.ui-components",
		"irtech.netcity.em.statreports.common"
	]);

require("./fill/controller.js");
require("approot/em/statReports/common/indicatorsRepository.coffee");
require("approot/em/statReports/common/indicatorViewController.coffee");
require("approot/global/directives/recursiveDirective.js");
require("approot/global/providers/uikit.controls.coffee");
require("approot/global/providers/netcity.helpers.coffee");
require("approot/global/providers/netcity.validation.coffee");

module.config(($routeProvider, $locationProvider) => {
	$routeProvider
		.when("/fill/", {
			templateUrl: "/static/dist/app/school/statReports/fill/template.html",
			controller: "FillIndicators.View.School"
		})
		.otherwise({
			redirectTo: "/fill/"
		});

	$locationProvider.hashPrefix('');
	$locationProvider.html5Mode({
		enabled: true,
		requireBase: true
	});
}).run(($rootScope, $appLoader) => {
	$rootScope.$on("$routeChangeSuccess",
		() => {
			$appLoader.hide();
		});
})



